from .base_wrapper import ListAbstractionsWrapper
from taf.config.testline.core import LTEEmuCore
from taf.config.testline.enb import LTEEmuEnb


class _LTEemuWrapper(ListAbstractionsWrapper):
    """
    All redirections for lteemu are contained inside this wrapper's properties
    """
    def __init__(self, tl_config):
        super(_LTEemuWrapper, self).__init__(tl_config)
        if self.tl_config.core is None:
            cores = []
        else:
            cores = [self.tl_config.core]

        if self.tl_config.enbs is None:
            enbs = []
        else:
            enbs = self.tl_config.enbs

        lteemu_core = self.get_instance(LTEEmuCore, cores)
        lteemu_enb = self.get_instance(LTEEmuEnb, enbs)
        if lteemu_core is not None:
            self._lteemu = lteemu_core
        elif lteemu_enb is not None:
            self._lteemu = lteemu_enb

    @property
    def dir_path(self):
        return self._lteemu.dir_path

    @property
    def cfg_filename(self):
        return self._lteemu.cfg_filename

    @property
    def addr(self):
        return self._lteemu.default_ssh_connection_details.addr

    @property
    def username(self):
        return self._lteemu.default_ssh_connection_details.username

    @property
    def password(self):
        return self._lteemu.default_ssh_connection_details.password
